local _, ns = ...
local L = ns.LocaleStrings("koKR")

--@localization(locale="koKR", format="lua_additive_table", handle-unlocalized="ignore")@

-- Hand-kept (11-23): by ithiel012 on Discord. Lines below win over CurseForge's.
L["..."] = "..."
L["(Complete)"] = "(완료)"
L["(current zone)"] = "(현재 지역)"
L["(first %d shown)"] = "(처음 %d개 표시)"
L["(map ID)"] = "(지도 ID)"
L["(named zone)"] = "(이름이 지정된 지역)"
L["(Shown while another bag addon is loaded; the panel writes the addon's name into its own line.)"] = "(다른 가방 애드온이 로드되어 있을 때 표시됩니다. 패널에는 해당 애드온의 이름이 별도의 줄에 표시됩니다.)"
L["(you)"] = "(나)"
L["{Module} is off. Its settings appear here once it's on."] = "{Module}이(가) 꺼져 있습니다. 켜면 이곳에 설정이 표시됩니다."
L["{n} change(s) need a reload"] = "{n}개의 변경 사항을 적용하려면 UI를 다시 불러와야 합니다."
L["* A cleaner chat with FlareUI's header and tabs\n* Class colours, short channel names and link icons\n* A copy button, and fading when quiet"] = "* FlareUI 헤더와 탭으로 더 깔끔해진 대화창\n* 직업 색상, 짧은 채널 이름 및 링크 아이콘\n* 복사 버튼과 대화가 없을 때 페이드 효과"
L["* A ring of spells, items, macros and more\n* Hold the key, point, release\n* Works with a gamepad too"] = "* 주문, 아이템, 매크로 등을 담은 방사형 메뉴\n* 키를 누른 채 가리킨 다음 놓기\n* 게임패드에서도 사용 가능"
L["* A square or round minimap\n* Coordinates, framerate and latency\n* A drawer for addon buttons"] = "* 사각형 또는 원형 미니맵\n* 좌표, 프레임률 및 지연 시간\n* 애드온 버튼을 모아 두는 서랍"
L["* An icon for each buff you or your group are missing\n* Food, flasks, elixirs, weapon oils and low supplies\n* Click an icon to cast or use it"] = "* 자신이나 파티에 부족한 강화 효과를 각각 아이콘으로 표시\n* 음식, 영약, 비약, 무기 기름 및 부족한 물품 표시\n* 아이콘을 클릭해 주문을 시전하거나 아이템 사용"
L["* Auto quests, auto repair and junk selling\n* Camera and vendor helpers\n* Hides clutter like error and zone text"] = "* 퀘스트 자동 수락, 자동 수리 및 잡동사니 판매\n* 카메라 및 상인 관련 편의 기능\n* 오류 메시지와 지역 텍스트 같은 불필요한 요소 숨기기"
L["* Blizzard's damage meter in a FlareUI frame\n* A threat view for tanks and damage dealers\n* Extra meter windows that dock as tabs"] = "* FlareUI 프레임에 표시되는 Blizzard 피해량 미터\n* 탱커와 공격 담당자를 위한 위협 수준 보기\n* 탭으로 고정할 수 있는 추가 미터 창"
L["* Cleaner tooltips with coloured borders\n* A health bar, target and threat lines if you want them\n* Tooltips that can follow your mouse"] = "* 색상 테두리로 더 깔끔해진 툴팁\n* 원하는 경우 생명력 바, 대상 및 위협 수준 표시\n* 마우스를 따라다니는 툴팁"
L["* Doggie art by |cffffd100Clari Turela|r.\n* |cffffd100sampconrad|r for the help with aura frames.\n* |cffffd100Jeor|r for the settings' new look idea.\n* |cffffd100parchinskiy|r for the round minimap.\n* |cffffd100Kabaday|r for the loot roll window.\n* |cffffd100Celbrund|r for the minimap Info Bar."] = "* 강아지 그림: |cffffd100Clari Turela|r.\n* 오라 프레임 제작에 도움을 준 |cffffd100sampconrad|r.\n* 설정 화면의 새로운 디자인 아이디어를 제공한 |cffffd100Jeor|r.\n* 원형 미니맵을 제작한 |cffffd100parchinskiy|r.\n* 전리품 주사위 창을 제작한 |cffffd100Kabaday|r.\n* 미니맵 정보 바를 제작한 |cffffd100Celbrund|r."
L["* Drag buttons in the drawer to reorder them\n* Changes apply after a reload\n* New addons go in the drawer\n* While OneForAll's \"Collect minimap buttons\" is on, its bar takes the minimap buttons: only the Addon Compartment entries are listed here"] = "* 서랍 안의 버튼을 드래그해 순서를 변경합니다.\n* 변경 사항은 UI를 다시 불러온 후 적용됩니다.\n* 새 애드온은 서랍에 추가됩니다.\n* OneForAll의 \"미니맵 버튼 모으기\"가 켜져 있으면 해당 애드온의 바가 미니맵 버튼을 가져갑니다. 이곳에는 애드온 보관함 항목만 표시됩니다."
L["* Nameplates for enemies and friends in the FlareUI style\n* Threat colours for tanks, damage and healers\n* Cast bars, your debuffs and crowd control on each plate\n* Every colour yours to pick"] = "* FlareUI 스타일의 적 및 아군 이름표\n* 탱커, 공격 담당자 및 치유 담당자를 위한 위협 수준 색상\n* 각 이름표에 시전 바, 자신의 약화 효과 및 군중 제어 표시\n* 모든 색상을 직접 선택 가능"
L["* Export: the profile in use as a text string to share\n* Import: paste a string and pick the parts to take, as a new profile or into the one in use"] = "* 내보내기: 현재 사용 중인 프로필을 공유할 수 있는 텍스트 문자열로 내보냅니다.\n* 가져오기: 문자열을 붙여넣고 가져올 항목을 선택합니다. 새 프로필로 만들거나 현재 프로필에 적용할 수 있습니다."
L["* FlareUI's bag and bank windows\n* Category filters and item levels\n* A loot roll window and a loot feed"] = "* FlareUI의 가방 및 은행 창\n* 범주 필터 및 아이템 레벨\n* 전리품 주사위 창 및 전리품 알림"
L["* FlareUI's borders, proc glows and status colours on your buttons\n* An XP bar, and hide the bars you don't use\n* Fake CM: spare bars as a cooldown tracker"] = "* 버튼에 FlareUI 테두리, 발동 효과 강조 표시 및 상태 색상 적용\n* 경험치 바와 사용하지 않는 바 숨기기\n* Fake CM: 여분의 바를 재사용 대기시간 추적기로 사용"
L["* FlareUI's look on the cooldown icons and bars\n* Keybinds and key presses on the icons\n* Growth, icon shape and fading in Edit Mode"] = "* 재사용 대기시간 아이콘과 바에 FlareUI 스타일 적용\n* 아이콘에 단축키와 키 입력 표시\n* 편집 모드에서 확장 방향, 아이콘 모양 및 페이드 설정"
L["* FlareUI's own quest tracker\n* Zone headings, quest levels and quest icons\n* Minimizes itself in instances or fights"] = "* FlareUI 전용 퀘스트 추적기\n* 지역 제목, 퀘스트 레벨 및 퀘스트 아이콘\n* 인스턴스에 입장하거나 전투가 시작되면 자동으로 최소화"
L["* Health, power, combo points and swing timers as bars you place anywhere\n* Paladin seals, flight timers and breath timers\n* Each bar set up in Edit Mode"] = "* 생명력, 자원, 연계 점수 및 공격 주기 타이머를 원하는 위치에 바 형태로 배치\n* 성기사 인장, 비행 타이머 및 호흡 타이머\n* 편집 모드에서 각 바 설정"
L["* In it: every FlareUI setting, and where FlareUI's frames sit on any Edit Mode layout\n* Not in it: Blizzard's bars and frames, which come with your Edit Mode layout\n* Switching profiles offers the layout the profile was set up on.\n* From another character, copy the layout with Copy Layout Code (About) or Sync Blizzard UI (General)."] = "* 포함 항목: 모든 FlareUI 설정 및 각 편집 모드 레이아웃에서 FlareUI 프레임의 위치\n* 제외 항목: 편집 모드 레이아웃에 포함되는 Blizzard의 바와 프레임\n* 프로필을 전환하면 해당 프로필에 설정된 레이아웃을 사용할 수 있습니다.\n* 다른 캐릭터에서 레이아웃을 복사하려면 레이아웃 코드 복사(정보) 또는 Blizzard UI 동기화(일반)를 사용하세요."
L["* New: a copy of the profile in use, or FlareUI's defaults\n* Rename: a new name for the profile in use\n* Delete: removes a profile you aren't using"] = "* 새로 만들기: 현재 사용 중인 프로필의 복사본 또는 FlareUI 기본값으로 새 프로필을 만듭니다.\n* 이름 변경: 현재 사용 중인 프로필의 이름을 변경합니다.\n* 삭제: 사용하지 않는 프로필을 제거합니다."
L["* Pick the Unit to change: enemy or friendly players, enemy or friendly NPCs, or Minor (minor mobs, pets, totems and guardians).\n* Pick a Preset. Change any setting and it becomes Custom, saved for that unit.\n* Live Preview shows everything the plate can show. Test in Game puts it on the plates around you."] = "* 변경할 유닛을 선택합니다: 적대적 또는 우호적 플레이어, 적대적 또는 우호적 NPC, 기타 유닛(하급 몬스터, 소환수, 토템 및 수호자).\n* 사전 설정을 선택합니다. 설정을 하나라도 변경하면 사용자 지정으로 전환되며 해당 유닛에 저장됩니다.\n* 실시간 미리보기에서는 이름표에 표시할 수 있는 모든 항목을 확인할 수 있습니다. 게임에서 테스트를 누르면 주변 유닛의 이름표에 적용됩니다."
L["* Player, target, focus, pet, party, raid and boss frames\n* Three styles: FlareUI, Forever and Modern\n* Size, text, auras and fading for each frame in Edit Mode"] = "* 플레이어, 대상, 주시 대상, 소환수, 파티, 공격대 및 우두머리 프레임\n* 세 가지 스타일: FlareUI, Forever 및 Modern\n* 편집 모드에서 각 프레임의 크기, 텍스트, 오라 및 페이드 설정"
L["* Spare action bars as a cooldown tracker: your spells, your order, any count per row.\n* Ticked bars can't be clicked and show only when Visibility says.\n* A button flashes when its cooldown ends.\n* Drag a spell onto them to change it, or use Fake CM Setup Mode (`/fui cm`).\n* Edit Mode always shows them: move and size them as any action bar."] = "* 여분의 행동 바를 재사용 대기시간 추적기로 사용합니다. 주문을 원하는 순서로 배치하고 행마다 원하는 개수만큼 표시할 수 있습니다.\n* 체크된 바는 클릭할 수 없으며 표시 여부 설정에 따라 나타납니다.\n* 재사용 대기시간이 끝나면 버튼이 깜박입니다.\n* 주문을 바 위로 드래그해 변경하거나 Fake CM 설정 모드(`/fui cm`)를 사용하세요.\n* 편집 모드에서는 항상 표시됩니다. 다른 행동 바처럼 이동하고 크기를 조절할 수 있습니다."
L["* Use Global Font Everywhere: sets every FlareUI font to Global. Sizes, outlines and shadows stay as they are.\n* Reset All Fonts: every FlareUI font, and the Global Font, back to defaults."] = "* 모든 곳에 전역 글꼴 사용: 모든 FlareUI 글꼴을 전역 글꼴로 설정합니다. 크기, 윤곽선 및 그림자는 그대로 유지됩니다.\n* 모든 글꼴 초기화: 모든 FlareUI 글꼴과 전역 글꼴을 기본값으로 되돌립니다."
L["* Your buffs and debuffs in FlareUI's look\n* Round or square icons, timers and sorting\n* Hide any aura, or always show it, on any frame\n* Size and placement in Edit Mode"] = "* FlareUI 스타일로 자신의 강화 효과와 약화 효과 표시\n* 원형 또는 사각형 아이콘, 타이머 및 정렬\n* 모든 프레임에서 원하는 오라를 숨기거나 항상 표시\n* 편집 모드에서 크기와 위치 설정"
L["/fui pad still switches. It never asks while ConsolePort or another controller addon is loaded."] = "/fui pad 명령어로 계속 전환할 수 있습니다. ConsolePort 또는 다른 컨트롤러 애드온이 로드되어 있으면 전환 여부를 묻지 않습니다."
L["/way is off in the Quality of Life settings."] = "편의 기능 설정에서 /way가 꺼져 있습니다."
L["/way usage:"] = "/way 사용법:"
L["%d found for \"%s\""] = "\"%s\"에서 %d개를 찾았습니다."
L["%s (copy)"] = "%s (복사본)"
L["%s (R%d)"] = "%s (R%d)"
L["%s by |cffb39ddbMalkkav|r. Type |cffffff00/fui|r for settings."] = "%s 제작: |cffb39ddbMalkkav|r. 설정을 열려면 |cffffff00/fui|r를 입력하세요."
L["%s finds gathering nodes by sliding the minimap under your cursor. While it scans, the map and what is on it (quest areas, icons) can flash or vanish for a moment.\n\nThat comes from the addon itself, not FlareUI, and happens on Blizzard's minimap too. NodeRadar, FarmMap and GatherMemory find nodes without moving the map."] = "%s은(는) 커서 아래에서 미니맵을 움직여 채집 지점을 찾습니다. 검색하는 동안 지도와 지도에 표시된 요소(퀘스트 지역, 아이콘)가 잠시 깜박이거나 사라질 수 있습니다.\n\n이는 FlareUI가 아니라 해당 애드온 자체에서 발생하는 현상이며 Blizzard 기본 미니맵에서도 나타납니다. NodeRadar, FarmMap 및 GatherMemory는 지도를 움직이지 않고 채집 지점을 찾습니다."
L["%s for bandages."] = "붕대용 %s."
L["%s holds %s. Put the radial there instead?"] = "%s에 %s이(가) 지정되어 있습니다. 대신 방사형 메뉴를 여기에 배치할까요?"
L["%s incoming!"] = "%s 접근 중!"
L["%s is bound to %s. Use it anyway?"] = "%s이(가) %s에 지정되어 있습니다. 그래도 사용하시겠습니까?"
L["%s is bound to %s. Use it for this radial anyway?"] = "%s이(가) %s에 지정되어 있습니다. 그래도 이 방사형 메뉴에 사용하시겠습니까?"
L["%s is handling your bags: turn it off to use these options."] = "%s이(가) 가방을 관리하고 있습니다. 이 옵션을 사용하려면 해당 애드온을 끄세요."
L["%s is handling your chat, so FlareUI's chat stays off. Turn %s off to use FlareUI's."] = "%s이(가) 대화창을 관리하고 있어 FlareUI 대화창이 꺼져 있습니다. FlareUI 대화창을 사용하려면 %s을(를) 끄세요."
L["%s is kept for Target Mouseover"] = "%s은(는) 마우스 오버 대상 지정용으로 예약되어 있습니다."
L["%s is kept for Target Mouseover. Pick a key without it."] = "%s은(는) 마우스 오버 대상 지정용으로 예약되어 있습니다. 해당 키를 제외한 다른 키를 선택하세요."
L["%s moves the minimap into its farming HUD while the HUD is on. The map is then the addon's: FlareUI puts its own minimap back when you turn the HUD off.\n\nIf the minimap still looks wrong after that, type /reload."] = "%s은(는) 채집 HUD가 켜져 있는 동안 미니맵을 해당 HUD 안으로 이동합니다. 이때 미니맵은 해당 애드온이 관리하며, HUD를 끄면 FlareUI가 자체 미니맵을 다시 표시합니다.\n\n그 후에도 미니맵이 정상적으로 표시되지 않으면 /reload를 입력하세요."
L["%s opens %s on this character."] = "%s을(를) 누르면 이 캐릭터에서 %s이(가) 열립니다."
L["%s to go"] = "%s 남음"
L["%s World Marker"] = "%s 월드 마커"
L["%s XP"] = "%s 경험치"
L["%s, kept"] = "%s, 예약됨"
L["`/cdm` opens it too."] = "`/cdm`으로도 열 수 있습니다."
L["`/fui cm` does the same. A reload ends it."] = "`/fui cm`으로도 같은 작업을 할 수 있습니다. UI를 다시 불러오면 종료됩니다."
L["`/fui` open settings.\n`/fui cm` Fake CM setup mode.\n`/fui pad` switch gamepad mode on/off.\n`/fui tour` the setup tour.\n`/kb` (or `/fui kb`) Quick Keybind Mode: point at a button and press a key to bind it."] = "`/fui` 설정 열기.\n`/fui cm` Fake CM 설정 모드.\n`/fui pad` 게임패드 모드 켜기/끄기.\n`/fui tour` 설정 안내 시작.\n`/kb` 또는 `/fui kb` 빠른 단축키 설정 모드: 버튼을 가리킨 다음 키를 눌러 단축키를 지정합니다."
L["+ New Radial"] = "+ 새 방사형 메뉴"
L["+%d more"] = "+%d개 더"
L["+%s quest XP"] = "+%s 퀘스트 경험치"
L["|cff1eff00Sample Item|r"] = "|cff1eff00예시 아이템|r"
L["|cffffd100Hide|r: the aura never shows on the ticked frames.\n|cffffd100Show|r: it always shows there, even when Only My Buffs, Only My Debuffs or Hide Buffs would leave it out. It comes after the frame's other buffs or debuffs."] = "|cffffd100숨기기|r: 선택한 프레임에는 해당 오라가 표시되지 않습니다.\n|cffffd100표시|r: 내 강화 효과만, 내 약화 효과만 또는 강화 효과 숨기기 설정으로 표시되지 않는 경우에도 항상 표시합니다. 프레임의 다른 강화 효과나 약화 효과 뒤에 표시됩니다."
L["0 removes the power bar."] = "0으로 설정하면 자원 바가 제거됩니다."
L["0/1 Agreed spelling of 'Mrglglgl'"] = "0/1 'Mrglglgl'의 표기에 동의함"
L["0/1 Excuses accepted by Garrosh"] = "0/1 가로쉬가 변명을 받아들임"
L["0/1 Glow described as 'cosy'"] = "0/1 빛 효과를 '아늑하다'고 표현함"
L["0/1 Left boot found in the Deadmines"] = "0/1 죽음의 폐광에서 왼쪽 장화를 찾음"
L["0/1 Plan with 32.33% odds rehearsed"] = "0/1 성공 확률 32.33%인 계획을 예행연습함"
L["0/1 Receipt for 'Emergency Gnoll Snacks'"] = "0/1 '비상용 놀 간식' 영수증"
L["1"] = "1"
L["1/1 Name shouted"] = "1/1 이름을 외침"
L["1/1 Wife found (she was in Goldshire)"] = "1/1 아내를 찾음 (골드샤이어에 있었음)"
L["10"] = "10"
L["10 Players"] = "10인"
L["10 Seconds"] = "10초"
L["100%"] = "100%"
L["100% is where you pull it. As a tank holding it, it shows your lead over the next."] = "100%가 어그로를 획득하는 기준입니다. 탱커가 대상을 붙잡고 있을 때는 다음 플레이어보다 앞선 위협 수준을 표시합니다."
L["1080p"] = "1080p"
L["1080p at 125%"] = "125% 배율의 1080p"
L["110%"] = "110%"
L["110% of the tank's threat in melee, 130% at range. Not shown while you are the tank."] = "근접 공격은 탱커 위협 수준의 110%, 원거리 공격은 130%입니다. 자신이 탱커일 때는 표시되지 않습니다."
L["120%"] = "120%"
L["130%"] = "130%"
L["140%"] = "140%"
L["1440p"] = "1440p"
L["1440p at 125%"] = "125% 배율의 1440p"
L["150%"] = "150%"
L["2"] = "2"
L["2/5 Questionable deductions explained"] = "2/5 수상한 추론을 설명함"
L["20"] = "20"
L["20%"] = "20%"
L["25 Players"] = "25인"
L["25%"] = "25%"
L["2D"] = "2D"
L["3"] = "3"
L["3/8 Leper gnomes reassured"] = "3/8 나병 노움들을 안심시킴"
L["30 Seconds"] = "30초"
L["30%"] = "30%"
L["35%"] = "35%"
L["4"] = "4"
L["4/8 Murlocs saying 'Hello' clearly"] = "4/8 '안녕하세요'라고 또렷하게 말하는 멀록"
L["40 Players"] = "40인"
L["4K"] = "4K"
L["5"] = "5"
L["5 Seconds"] = "5초"
L["50%"] = "50%"
L["6/10 Kobold candles confiscated"] = "6/10 코볼트 양초를 압수함"
L["60%"] = "60%"
L["70%"] = "70%"
L["80%"] = "80%"
L["90%"] = "90%"
L["A bar while you're on a flight path: where you're going and the time left."] = "비행 경로를 이용하는 동안 목적지와 남은 시간을 표시하는 바입니다."
L["A big icon right of the plate while the unit is stunned, feared, polymorphed or otherwise controlled."] = "유닛이 기절, 공포, 변이 또는 그 밖의 군중 제어 효과를 받는 동안 이름표 오른쪽에 큰 아이콘을 표시합니다."
L["A bright line and a soft glow at the front of the health bar. It flashes when health changes."] = "생명력 바 앞쪽에 밝은 선과 은은한 빛을 표시합니다. 생명력이 변하면 깜박입니다."
L["A button beside Send Mail's \"To:\" lists:\n* The last character you mailed\n* Your other characters here"] = "우편 보내기의 \"받는 사람:\" 옆에 버튼을 추가하여 다음 목록을 표시합니다.\n* 마지막으로 우편을 보낸 캐릭터\n* 이 서버의 다른 캐릭터"
L["A button for you and each party member: aim at a person to cast on them."] = "자신과 각 파티원에게 버튼을 제공합니다. 대상에게 버튼을 가리켜 주문을 시전할 수 있습니다."
L["A camera that zooms out further"] = "더 멀리 확대 축소할 수 있는 카메라"
L["A cast bar under each member."] = "각 구성원 아래에 시전 바를 표시합니다."
L["A cast bar under the health bar while the unit casts. A cast you can't interrupt turns grey with a shield."] = "유닛이 주문을 시전하는 동안 생명력 바 아래에 시전 바를 표시합니다. 차단할 수 없는 시전은 방패 아이콘과 함께 회색으로 표시됩니다."
L["A character shows up once you've logged in on it."] = "해당 캐릭터로 로그인하면 목록에 표시됩니다."
L["A clash means two radials share a key. The first in the list wins."] = "충돌은 두 방사형 메뉴가 같은 키를 사용하는 경우를 뜻합니다. 목록에서 먼저 나오는 메뉴가 우선 적용됩니다."
L["A cleaner chat frame with a customisable header."] = "사용자 지정 가능한 헤더를 갖춘 더 깔끔한 대화창입니다."
L["A click drinks one from your bags. Any rank of an elixir counts."] = "클릭하면 가방에 있는 비약을 하나 마십니다. 모든 등급의 비약이 해당됩니다."
L["A dark outline around the letters."] = "글자 주위에 어두운 윤곽선을 표시합니다."
L["A dispellable debuff makes the frame's border pulse in its type's colour. In the ring styles the portrait's ring pulses too."] = "해제 가능한 약화 효과가 있으면 해당 효과 유형의 색상으로 프레임 테두리가 맥동합니다. 링 스타일에서는 초상화의 링도 함께 맥동합니다."
L["A dispellable debuff on a friendly unit makes the frame's border pulse in its type's colour."] = "우호적 유닛에게 해제 가능한 약화 효과가 있으면 해당 효과 유형의 색상으로 프레임 테두리가 맥동합니다."
L["A dispellable debuff on you makes the frame's border pulse in its type's colour. In the ring styles the portrait's ring pulses too."] = "자신에게 해제 가능한 약화 효과가 있으면 해당 효과 유형의 색상으로 프레임 테두리가 맥동합니다. 링 스타일에서는 초상화의 링도 함께 맥동합니다."
L["A drop shadow under the letters.\n* Soft: 1 pixel away\n* Strong: 2 pixels away"] = "글자 아래에 그림자를 표시합니다.\n* 약하게: 1픽셀 거리\n* 강하게: 2픽셀 거리"
L["A FlareUI button in the game menu (Esc), right under Shop. It opens FlareUI's settings."] = "게임 메뉴(Esc)의 상점 바로 아래에 FlareUI 버튼을 추가합니다. 버튼을 누르면 FlareUI 설정이 열립니다."
L["A gold dragon on elites, a silver one on rares, on the plate's top right corner."] = "정예 유닛에는 금색 용, 희귀 유닛에는 은색 용을 이름표 오른쪽 위에 표시합니다."
L["A gold edge and a light on the active button:\n* Your stance or form\n* A queued Heroic Strike, Cleave, Maul or Raptor Strike (it pulses)\n* Auto Shot and wands while they repeat"] = "활성화된 버튼에 금색 테두리와 빛을 표시합니다.\n* 현재 태세 또는 변신 형태\n* 예약된 영웅의 일격, 회전베기, 후려치기 또는 랩터의 일격 (맥동 효과)\n* 자동 사격 및 반복 시전 중인 마법봉 공격"
L["A green \">\" before whispers you get and a red \"<\" before ones you send, instead of \"whispers:\" and \"To\"."] = "받은 귓속말 앞에는 초록색 \">\", 보낸 귓속말 앞에는 빨간색 \"<\"를 표시합니다. 기존의 \"귓속말:\" 및 \"받는 사람\" 표시를 대신합니다."
L["A header with your tabs and buttons"] = "탭과 버튼이 있는 헤더"
L["A health bar on unit tooltips, in FlareUI's look:\n* Below: under the tooltip\n* Inside: at the tooltip's bottom, which grows to hold it"] = "유닛 툴팁에 FlareUI 스타일의 생명력 바를 표시합니다.\n* 아래: 툴팁 아래쪽에 표시\n* 내부: 생명력 바를 포함하도록 확장되는 툴팁의 아래쪽에 표시"
L["A key that minimizes or opens the tracker."] = "추적기를 최소화하거나 여는 키입니다."
L["A little more space between chat lines."] = "대화 줄 사이의 간격을 조금 더 넓힙니다."
L["A Meter tab beside your chat tabs shows the meter inside the chat window. Pick when it opens on its own; tick as many as you like:\n* Open When Clicked: only when you click it\n* Open in Combat: during fights, back to the chat after\n* Open in a Group: while you're in a group\n* Open at Login: it starts open"] = "대화 탭 옆의 미터 탭을 통해 대화창 안에 미터를 표시합니다. 자동으로 열리는 조건을 원하는 만큼 선택하세요.\n* 클릭할 때 열기: 탭을 클릭했을 때만 열립니다.\n* 전투 중 열기: 전투 중 열리고 전투가 끝나면 대화창으로 돌아갑니다.\n* 파티에 있을 때 열기: 파티에 속해 있는 동안 열립니다.\n* 로그인할 때 열기: 로그인하면 열린 상태로 시작합니다."
L["A minimap with square and round styles."] = "사각형 및 원형 스타일을 지원하는 미니맵입니다."
L["A new one hides on every frame. Its row below can change it to Show and pick the frames."] = "새 항목은 모든 프레임에서 숨김 상태로 추가됩니다. 아래쪽 행에서 표시로 변경하고 적용할 프레임을 선택할 수 있습니다."
L["A new radial starts on this character only."] = "새 방사형 메뉴는 현재 캐릭터에서만 사용할 수 있습니다."
L["A newly learned rank replaces the lower rank on your bars."] = "새로 배운 상위 등급이 행동 바에 있는 하위 등급을 대체합니다."
L["A note icon in each chat window's top right corner. Click it to copy that window's lines."] = "각 대화창 오른쪽 위에 메모 아이콘을 표시합니다. 클릭하면 해당 대화창의 내용을 복사합니다."
L["A paw marks the food your hunter pet eats."] = "발바닥 아이콘으로 사냥꾼 소환수가 먹는 음식을 표시합니다."
L["A quest mark beside the plate on enemies your quests need. It sits on the side away from the level, or on the right with no level beside the bar."] = "퀘스트에 필요한 적의 이름표 옆에 퀘스트 징표를 표시합니다. 레벨 표시와 반대쪽에 배치하며, 바 옆에 레벨이 없으면 오른쪽에 표시합니다."
L["A quest mark on enemies you need for a quest."] = "퀘스트에 필요한 적에게 퀘스트 징표를 표시합니다."
L["A quest you accept doesn't take the focus. The quest you had focused stays focused."] = "퀘스트를 수락해도 주시 대상이 바뀌지 않습니다. 기존에 주시하던 퀘스트가 계속 주시 상태로 유지됩니다."
L["A red line on the Threat tab's bars, where you would pull the enemy off the tank."] = "탱커에게서 적의 어그로를 빼앗게 되는 지점을 위협 수준 탭의 바에 빨간색 선으로 표시합니다."
L["A ring of spells, items, macros and more. Hold the key, point, release."] = "주문, 아이템, 매크로 등을 담은 방사형 메뉴입니다. 키를 누른 채 가리킨 다음 놓으세요."
L["A roll you pass on leaves the window. The icon at the top opens Blizzard's loot history. Placed and scaled in Edit Mode as \"FlareUI Loot Rolls\"."] = "포기한 전리품 주사위 항목은 창에서 사라집니다. 상단 아이콘을 클릭하면 Blizzard의 전리품 기록이 열립니다. 편집 모드에서 \"FlareUI Loot Rolls\"로 위치와 크기를 조절할 수 있습니다."
L["A short rumble when a spell lights up on your action bars."] = "행동 바의 주문에 발동 효과가 나타날 때 짧게 진동합니다."
L["A short tag after the quest name:\n* + for elite\n* g3 for a group of 3\n* d for dungeon, r for raid\n* pvp for PvP"] = "퀘스트 이름 뒤에 짧은 태그를 표시합니다.\n* +: 정예\n* g3: 3인 파티\n* d: 던전, r: 공격대\n* pvp: PvP"
L["A short time in blue before each message, like <12:30>."] = "각 메시지 앞에 <12:30>과 같은 파란색 짧은 시간 표시를 추가합니다."
L["A small frame for each pet, under its owner."] = "각 소환수의 소유자 아래에 작은 프레임을 표시합니다."
L["A small frame for each pet: under its owner, or beside it."] = "각 소환수의 작은 프레임을 소유자 아래 또는 옆에 표시합니다."
L["A soft glow round your target's plate and its level, in the bar's own colour."] = "대상의 이름표와 레벨 주위에 해당 바의 색상으로 은은한 빛을 표시합니다."
L["A sound as Pull Warning starts, so you hear it without watching the meter."] = "풀 경고가 시작될 때 소리를 재생하므로 미터를 보고 있지 않아도 알 수 있습니다."
L["A sound when a reminder appears. Picking one plays it."] = "알림이 나타날 때 소리를 재생합니다. 소리를 선택하면 미리 재생됩니다."
L["A sound when someone whispers you. Picking one plays it."] = "누군가 귓속말을 보내면 소리를 재생합니다. 소리를 선택하면 미리 재생됩니다."
L["A spark crosses the bar during the global cooldown."] = "전역 재사용 대기시간 동안 바를 가로지르는 반짝임을 표시합니다."
L["A spark crosses the bar for five seconds after you spend mana. Spirit regeneration starts again when it ends."] = "마나를 소모한 후 5초 동안 바를 가로지르는 반짝임을 표시합니다. 효과가 끝나면 정신력 재생이 다시 시작됩니다."
L["A spell or buff to keep up: its name or spell ID. Several, separated by commas, count as one (any of them). An item: item:ID."] = "유지할 주문 또는 강화 효과의 이름이나 주문 ID를 입력합니다. 여러 항목을 쉼표로 구분해 입력하면 그중 하나만 있어도 유지된 것으로 간주합니다. 아이템은 item:ID 형식으로 입력합니다."
L["A square map with Forever's day and night cycle"] = "Forever의 낮과 밤 주기가 적용되는 사각형 지도"
L["A tab that shows several kinds keeps your current one. A Party or Raid tab sets Say while you're not in one."] = "여러 종류를 표시하는 탭은 현재 채널을 유지합니다. 파티 또는 공격대 탭은 해당 그룹에 속해 있지 않을 때 일반 대화로 설정됩니다."
L["A Threat tab, so you know when to stop"] = "언제 공격을 멈춰야 하는지 알 수 있는 위협 수준 탭"
L["A Threat Within"] = "내부의 위협"
L["A timer for each weapon's next swing."] = "각 무기의 다음 공격까지 남은 시간을 표시합니다."
L["A Train All button at class and profession trainers."] = "직업 및 전문 기술 상인에게 모두 배우기 버튼을 추가합니다."
L["A Train All button at trainers"] = "상인에게 모두 배우기 버튼을 추가합니다."
L["A weapon's or armour's item level at the bottom of its tooltip."] = "무기 또는 방어구의 아이템 레벨을 툴팁 아래쪽에 표시합니다."
L["Abilities glow when they become usable or a proc buff empowers them:\n* Overpower, Execute, Hammer of Wrath and more\n* Ice Lance with Fingers of Frost"] = "기술을 사용할 수 있게 되거나 발동 효과가 기술을 강화하면 빛납니다.\n* 제압, 마무리 일격, 천벌의 망치 등\n* 두뇌 빙결 효과가 활성화된 얼음창"
L["About"] = "정보"
L["Above"] = "위"
L["Above the Frame"] = "프레임 위"
L["Above the Frame, Left"] = "프레임 위, 왼쪽"
L["Above the Frame, Right"] = "프레임 위, 오른쪽"
L["Above the Tank"] = "탱커 위"
L["Absorb Texture"] = "흡수 텍스처"
L["Accept Resurrections"] = "부활 수락"
L["Accept Summons"] = "소환 수락"
L["Action Bar 1"] = "행동 바 1"
L["Action Bar 2"] = "행동 바 2"
L["Action Bar 3"] = "행동 바 3"
L["Action Bar 4"] = "행동 바 4"
L["Action Bar 5"] = "행동 바 5"
L["Action Bar 6"] = "행동 바 6"
L["Action Bar 7"] = "행동 바 7"
L["Action Bar 8"] = "행동 바 8"
L["Action bar spells go off when you press the key, not when you let go."] = "키를 놓을 때가 아니라 누르는 순간 행동 바의 주문이 시전됩니다."
L["Action Bars"] = "행동 바"
L["Action buttons and FlareUI's XP bar."] = "행동 버튼 및 FlareUI 경험치 바"
L["Action/Data Bars"] = "행동/데이터 바"
L["Activation"] = "활성화"
L["Active Highlight"] = "활성 상태 강조 표시"
L["Active Profile"] = "활성 프로필"
L["Add"] = "추가"
L["Add an Aura"] = "오라 추가"
L["Add an aura you don't have right now, by its spell ID."] = "현재 자신에게 없는 오라를 주문 ID로 추가합니다."
L["Add by Spell ID"] = "주문 ID로 추가"
L["Add Custom Reminder"] = "사용자 지정 알림 추가"
L["Add to New Group..."] = "새 그룹에 추가..."
L["Addon button"] = "애드온 버튼"
L["Addon Button Drawer"] = "애드온 버튼 보관함"
L["Addon Buttons"] = "애드온 버튼"
L["Addon Language"] = "애드온 언어"
L["Addon Reset"] = "애드온 초기화"
L["Addons in the Drawer"] = "보관함에 있는 애드온"
L["Adds \"Target: Name\" to unit tooltips."] = "유닛 툴팁에 \"대상: 이름\"을 추가합니다."
L["Adds item and spell IDs."] = "아이템 및 주문 ID를 표시합니다."
L["Adds the player's rank after their guild's name."] = "플레이어의 길드 이름 뒤에 계급을 표시합니다."
L["Adds your own frame to the party frames."] = "파티 프레임에 자신의 프레임을 추가합니다."
L["Advanced Cooldown Settings"] = "고급 재사용 대기시간 설정"
