L["All Buffs"] = "모든 강화 효과"
L["All Characters"] = "모든 캐릭터"
L["All Debuffs"] = "모든 약화 효과"
L["All Items"] = "모든 아이템"
L["All Quests"] = "모든 퀘스트"
L["All Tooltips"] = "모든 툴팁"
L["All Tooltips and None clear the others. Tick only the kinds you want at your mouse."] = "모든 툴팁과 없음은 다른 항목의 선택을 해제합니다. 마우스 위치에 표시할 종류만 선택하세요."
L["All your addon buttons tucked into one bag"] = "모든 애드온 버튼을 하나의 가방에 모읍니다."
L["All your bags in one window. The same as Blizzard's Use Combined Bags option."] = "모든 가방을 하나의 창에 표시합니다. 블리자드의 가방 통합 사용 옵션과 동일합니다."
L["Alright chums, let's do this."] = "좋아, 친구들. 시작해 보자고."
L["also bound to %s"] = "또한 %s에 지정됨"
L["Also in There"] = "여기에도 표시"
L["Alt"] = "Alt"
L["Always"] = "항상"
L["Always clears the others; nothing ticked means Always. Fake CM Setup Mode always shows them."] = "항상은 다른 항목의 선택을 해제합니다. 아무것도 선택하지 않으면 항상 표시됩니다. 가짜 CM 설정 모드에서는 항상 표시됩니다."
L["Always clears the others; nothing ticked means Always. Opening your spellbook always shows it."] = "항상은 다른 항목의 선택을 해제합니다. 아무것도 선택하지 않으면 항상 표시됩니다. 주문책을 열면 항상 표시됩니다."
L["Always Show Plates"] = "이름표 항상 표시"
L["An eye in the top right corner marks gear whose appearance you haven't collected yet and can learn."] = "오른쪽 위 모서리의 눈 아이콘은 아직 형상을 수집하지 않았으며 배울 수 있는 장비를 표시합니다."
L["An icon for each buff you're missing, on you or your group. Click it to cast the buff."] = "자신이나 파티에 없는 각 강화 효과를 아이콘으로 표시합니다. 아이콘을 클릭하면 해당 강화 효과를 시전합니다."
L["An icon for each debuff type you can dispel. On the Portrait puts them two to a row in its middle (without a portrait, or in Raid Style, in the middle of the health bar). Anywhere else they line up."] = "해제할 수 있는 각 약화 효과 유형을 아이콘으로 표시합니다. 초상화에서는 가운데에 한 줄에 두 개씩 배치합니다. 초상화가 없거나 공격대 스타일에서는 생명력 바 가운데에 배치하며, 그 외의 위치에서는 한 줄로 나열됩니다."
L["An icon lights up while you hold its key, as an action button does."] = "행동 버튼처럼 해당 키를 누르고 있는 동안 아이콘이 빛납니다."
L["An icon when something needs looking after:\n* Weapon Oil / Stone: a weapon with no oil or stone on it. Click to use one, right-click to pick which\n* Low Supplies: low on reagents (Soul Shards, Arcane Powder, candles, Symbols of Kings...) or a hunter's ammo (under 200)\n* Low Durability: any gear below 20%\n* Worn Trinkets: an Argent Dawn trinket or Carrot on a Stick still on in a dungeon or raid\n* Camping and Rest: Camp Benefits missing, or under three Well-Rested stacks with a Cozy Sleeping Bag (click to use it)\n* Gathering Tracking: Find Herbs or Find Minerals known but off"] = "관리가 필요한 항목이 있을 때 아이콘을 표시합니다:\n* 무기 기름 / 숫돌: 무기에 기름이나 숫돌 효과가 없을 때 표시합니다. 클릭하면 사용하고, 오른쪽 클릭하면 사용할 항목을 선택합니다.\n* 물품 부족: 재료(영혼의 조각, 신비한 가루, 양초, 왕의 징표 등) 또는 사냥꾼의 탄약이 부족할 때 표시합니다. 탄약은 200개 미만일 때 해당합니다.\n* 낮은 내구도: 내구도가 20% 미만인 장비가 있을 때 표시합니다.\n* 낡은 장신구: 던전이나 공격대에서 은빛 여명회 장신구 또는 당근 달린 지팡이를 착용하고 있을 때 표시합니다.\n* 야영 및 휴식: 야영 혜택이 없거나, 아늑한 침낭을 사용했을 때 충분히 휴식함 중첩이 3회 미만이면 표시합니다. 클릭하면 침낭을 사용합니다.\n* 채집 추적: 약초 찾기 또는 광물 찾기를 알고 있지만 활성화하지 않았을 때 표시합니다."
L["An icon while you have no Well Fed buff or no flask. Choose where it shows on the When and Where tab."] = "포만감 강화 효과나 영약 효과가 없을 때 아이콘을 표시합니다. 표시 위치는 시점 및 위치 탭에서 선택하세요."
