L["Bags counts used and total slots. Durability is your most worn piece. Coords (Simple) drops the decimals: 45, 62 instead of 45.3, 62.1."] = "가방은 사용 중인 슬롯과 전체 슬롯 수를 표시합니다. 내구도는 가장 많이 손상된 장비를 기준으로 표시합니다. 좌표(간단)는 소수점을 생략하여 45.3, 62.1 대신 45, 62로 표시합니다."
L["Bags full, not enough money and quest log full still show."] = "가방이 가득 참, 돈이 부족함, 퀘스트 로그가 가득 참 알림은 계속 표시됩니다."
