L["Bankers, vendors, trainers, innkeepers and flight masters open their window at once when they have nothing else to say."] = "은행원, 상인, 기술 전문가, 여관 주인 및 비행 조련사가 다른 대화 내용이 없으면 대화와 동시에 해당 창을 엽니다."
