L["Bars and frames in the same fade group:\n* Fade together\n* Share their Visibility, Show Speed, Hide Speed and Faded Opacity"] = "같은 페이드 그룹에 속한 바와 프레임은 다음과 같이 동작합니다:\n* 함께 페이드됩니다.\n* 표시 여부, 표시 속도, 숨김 속도 및 페이드 상태 불투명도를 공유합니다."
L["Behaviour"] = "동작 방식"
L["Behind Bars"] = "바 뒤"
L["Behind Bars needs FlareUI's action bars on."] = "바 뒤 기능을 사용하려면 FlareUI의 행동 바를 활성화해야 합니다."
L["Below"] = "아래"
L["Below and Above keep the latest messages in view."] = "아래와 위 설정은 최신 메시지가 계속 보이도록 유지합니다."
L["Below the Frame"] = "프레임 아래"
