L["Below the Frame, Right"] = "프레임 아래, 오른쪽"
L["Below this much health, the bar turns the execute colour. A thin line marks where it starts. Automatic uses your class's own, such as a warrior's Execute or a paladin's Hammer of Wrath."] = "생명력이 이 수치보다 낮아지면 바가 마무리 공격 색상으로 바뀝니다. 시작 지점은 얇은 선으로 표시됩니다. 자동 설정은 전사의 제압이나 성기사의 천벌의 망치처럼 직업에 해당하는 기술을 기준으로 합니다."
L["Better NPC Names"] = "향상된 NPC 이름"
L["Better Player Names"] = "향상된 플레이어 이름"
L["Better Timestamps"] = "향상된 시간 표시"
L["Big"] = "크게"
L["Big defensives on the unit, its own or ones others put on it, left of the plate."] = "해당 유닛에게 걸린 강력한 방어 효과를 이름표 왼쪽에 표시합니다. 유닛 자신의 효과와 다른 사람이 걸어 준 효과 모두 표시됩니다."
L["Binds when picked up"] = "획득 시 귀속"
L["Blessing"] = "축복"
L["Blizzard"] = "블리자드"
L["Blizzard Frames"] = "블리자드 프레임"
L["Blizzard limits which auras can be filtered. If one here doesn't hide or show, this is why:\n* Allowed: buffs on you, your pet and your group, and debuffs on enemies.\n* Blocked: debuffs on you or a friend, except a few harmless ones such as Sated."] = "블리자드는 필터링할 수 있는 오라를 제한합니다. 여기에서 특정 오라가 숨겨지거나 표시되지 않는다면 다음 제한 때문입니다:\n* 허용: 자신, 소환수 및 파티원의 강화 효과와 적의 약화 효과\n* 차단: 자신이나 아군에게 걸린 약화 효과. 포만함처럼 해가 없는 일부 효과는 예외입니다."
L["Blizzard's action bars in FlareUI's style."] = "블리자드의 행동 바를 FlareUI 스타일로 표시합니다."
L["Blizzard's bars, sharpened: red when out of range, blue with no mana, glows on procs."] = "블리자드의 바를 개선합니다. 사거리 밖에서는 빨간색, 마나가 없으면 파란색으로 표시하고 발동 효과가 발생하면 빛납니다."
L["Blizzard's bronze frame and portrait ring."] = "블리자드의 청동색 프레임과 초상화 테두리입니다."
L["Blizzard's Cooldown Manager in FlareUI's style."] = "블리자드의 재사용 대기시간 관리자를 FlareUI 스타일로 표시합니다."
L["Blizzard's damage meter in a FlareUI frame, with a threat view."] = "블리자드의 피해량 미터를 위협 수준 보기 기능과 함께 FlareUI 프레임으로 표시합니다."
L["Blizzard's damage meter is off. FlareUI's meter needs it."] = "블리자드의 피해량 미터가 비활성화되어 있습니다. FlareUI 미터를 사용하려면 활성화해야 합니다."
L["Blizzard's meter in a FlareUI frame"] = "블리자드 미터를 FlareUI 프레임으로 표시합니다."
L["Blizzard's own text takes the Global Font too: menus, windows, quest text, nameplates, combat text and more. Sizes and outlines stay as they are."] = "메뉴, 창, 퀘스트 텍스트, 이름표, 전투 텍스트 등 블리자드 기본 텍스트에도 전역 글꼴을 적용합니다. 글꼴 크기와 외곽선은 그대로 유지됩니다."
L["Blizzard's own Visibility for the meter, in Edit Mode, hides it at the start of some fights, and FlareUI can't bring it back until the fight ends. Set it to Always there and let FlareUI's Visibility decide."] = "편집 모드에서 미터의 블리자드 자체 표시 여부 설정을 사용하면 일부 전투가 시작될 때 미터가 숨겨지고, 전투가 끝날 때까지 FlareUI가 다시 표시할 수 없습니다. 해당 설정을 항상 표시로 지정하고 FlareUI의 표시 여부 설정에 맡기세요."
L["Blizzard's slot frame on every button of bars 1 to 8 and the pet bar, even where a bar hides its art."] = "바의 그래픽이 숨겨진 경우에도 1~8번 바와 소환수 바의 모든 버튼에 블리자드 슬롯 프레임을 표시합니다."
