L["Breath"] = "호흡"
L["Bronze (Clean)"] = "청동색 (깔끔)"
L["Bronze (Header)"] = "청동색 (머리글)"
L["Buff and debuff icons."] = "강화 효과 및 약화 효과 아이콘입니다."
L["Buff Reminders"] = "강화 효과 알림"
L["Buff Reminders: an icon for each buff you or your group are missing."] = "강화 효과 알림: 자신이나 파티에 없는 각 강화 효과를 아이콘으로 표시합니다."
L["Buff Size"] = "강화 효과 크기"
L["Buffs"] = "강화 효과"
L["Buffs & Debuffs"] = "강화 효과 및 약화 효과"
L["Buffs above the bar, from its left end (centred with Debuffs off). Tick filters to narrow them down; each one you tick must match:\n* Only Purgeable: ones you or your group can remove\n* Only Important: the ones the game marks as important\n* Only Mine: the ones you cast"] = "바 위쪽의 왼쪽 끝부터 강화 효과를 표시합니다. 약화 효과가 꺼져 있으면 가운데 정렬됩니다. 필터를 선택해 표시 대상을 좁힐 수 있으며, 선택한 필터는 모두 일치해야 합니다:\n* 해제 가능한 효과만: 자신이나 파티원이 해제할 수 있는 효과\n* 중요 효과만: 게임에서 중요하다고 표시한 효과\n* 내 효과만: 자신이 시전한 효과"
L["Buffs as Blizzard's raid frames pick them: mostly your own heals over time and buffs."] = "블리자드 공격대 프레임과 동일한 방식으로 강화 효과를 선택해 표시합니다. 주로 자신이 시전한 지속 치유 효과와 강화 효과가 표시됩니다."
L["Buffs/Debuffs"] = "강화 효과/약화 효과"
L["Button Names"] = "버튼 이름"
L["Button Scale"] = "버튼 배율"
L["Buttons"] = "버튼"
L["Buttons beside each quest's title. Tick the ones you want:\n* Quest Icon: a round icon, as on Blizzard's tracker: \"…\" while in progress, \"?\" when ready to turn in. Click it to focus the quest\n* Focus Button: a small dot, yellow on the focused quest. Click it to focus the quest\n* Voice Button: on the right, plays, stops or replays the quest's voice line (Spoken)"] = "각 퀘스트 제목 옆에 표시할 버튼입니다. 원하는 항목을 선택하세요:\n* 퀘스트 아이콘: 블리자드 추적기와 같은 둥근 아이콘입니다. 진행 중에는 \"…\", 완료 준비가 되면 \"?\"로 표시됩니다. 클릭하면 해당 퀘스트에 초점을 맞춥니다.\n* 초점 버튼: 작은 점으로 표시되며, 초점을 맞춘 퀘스트에서는 노란색으로 표시됩니다. 클릭하면 해당 퀘스트에 초점을 맞춥니다.\n* 음성 버튼: 오른쪽에 표시되며 퀘스트 음성 대사(음성)를 재생, 정지 또는 다시 재생합니다."
L["Buttons in the tracker's header, beside the minimize button. Tick the ones you want:\n* Filter: all tracked quests, or only this zone's\n* Sort: click to change how quests are sorted, right-click to go back\n* Auto Accept: a \"!\" that turns Auto Accept Quests on and off\n* Auto Turn-In: a \"?\" that turns Auto Turn-In Quests on and off\nA lit button is on."] = "추적기의 최소화 버튼 옆 머리글에 표시할 버튼입니다. 원하는 항목을 선택하세요:\n* 필터: 추적 중인 모든 퀘스트 또는 현재 지역의 퀘스트만 표시합니다.\n* 정렬: 클릭하면 퀘스트 정렬 방식을 변경하고, 오른쪽 클릭하면 이전 방식으로 돌아갑니다.\n* 자동 수락: \"!\" 버튼으로 퀘스트 자동 수락을 켜거나 끕니다.\n* 자동 완료: \"?\" 버튼으로 퀘스트 자동 완료를 켜거나 끕니다.\n불이 켜진 버튼은 활성화된 상태입니다."
L["Buttons on the chat's header. Tick the ones you want:\n* Social: friends and Quick Join\n* Chat Channels: channels and voice chat\n* Chat Menu: emotes, languages and chat options\n* Volume: the game's master volume. Click to mute or unmute, mouse wheel for louder or quieter"] = "채팅 머리글에 표시할 버튼입니다. 원하는 항목을 선택하세요:\n* 소셜: 친구 및 빠른 참가\n* 채팅 채널: 채널 및 음성 채팅\n* 채팅 메뉴: 감정 표현, 언어 및 채팅 옵션\n* 음량: 게임의 전체 음량입니다. 클릭하면 음소거하거나 해제하고, 마우스 휠을 사용하면 음량을 높이거나 낮춥니다."
L["Buttons with an item you wear (a trinket, a helmet you use) get a border in the item's quality colour, instead of Blizzard's faint green."] = "장착 중인 아이템(장신구나 착용 중인 투구 등)이 있는 버튼은 블리자드의 희미한 녹색 대신 아이템 품질에 해당하는 색상의 테두리로 표시됩니다."
L["Buying %d of %d..."] = "%d개 중 %d개 구매 중..."
L["Buys a stack at a time, as far as your gold, bag space and the vendor's stock allow."] = "보유 골드, 가방 공간 및 상인의 재고가 허용하는 범위에서 한 묶음씩 구매합니다."
