L["Changing Sundial reloads the interface. Without it, a drawer that opened from the sundial opens from Blizzard's small addon button instead."] = "Sundial을 변경하면 인터페이스를 다시 불러옵니다. Sundial이 없으면 Sundial에서 열리던 보관함이 대신 블리자드의 작은 애드온 버튼에서 열립니다."
