L["Class Buffs"] = "직업 강화 효과"
L["Class buffs you're reminded of only if you tick them: Shadow Protection and Moonkin Form."] = "선택한 직업 강화 효과만 알림으로 표시합니다. 해당 효과는 어둠의 보호와 달빛야수 변신입니다."
L["Class Colours"] = "직업 색상"
L["Class Default"] = "직업 기본값"
