L["Coming soon"] = "출시 예정"
L["commands"] = "명령어"
L["Compact raid tiles, centred as the raid grows, with:\n* Main tank frames\n* A reminder of the buffs you can give"] = "공격대 인원이 늘어날수록 가운데 정렬되는 간결한 공격대 타일을 표시합니다. 다음 기능이 포함됩니다:\n* 주 탱커 프레임\n* 자신이 부여할 수 있는 강화 효과 알림"
