L["Enemy NPCs you can't attack yet show only their name. Their full plate comes back once you can attack them."] = "아직 공격할 수 없는 적 NPC는 이름만 표시됩니다. 공격할 수 있게 되면 전체 이름표가 다시 표시됩니다."
