L["Errors FlareUI caught, to copy into a bug report (\"/fui errors clear\" empties the list)."] = "FlareUI가 감지한 오류입니다. 버그 보고서에 복사해서 사용할 수 있습니다(\"/fui errors clear\"를 입력하면 목록이 비워집니다)."
L["ESC Menu"] = "ESC 메뉴"
L["Every addon's minimap button in one drawer. Click the day/night badge to open it."] = "모든 애드온의 미니맵 버튼을 하나의 보관함에 모읍니다. 낮/밤 배지를 클릭하면 열립니다."
L["Every buff on the boss, such as enrages and shields."] = "격노와 보호막 등 우두머리에게 걸린 모든 강화 효과입니다."
L["Every colour the plates paint, next to sample plates:\n* Reaction and tapped\n* Threat, as a tank and as damage or healer\n* Cast bar, target border, heals and shields\nChange any colour and the palette becomes Custom."] = "예시 이름표 옆에서 이름표에 사용되는 모든 색상을 확인할 수 있습니다:\n* 반응 및 선점 상태\n* 탱커, 공격 담당자 또는 치유 담당자일 때의 위협 수준\n* 시전 바, 대상 테두리, 치유 및 보호막\n색상을 하나라도 변경하면 팔레트가 사용자 지정으로 바뀝니다."
L["Every colour the XP bar paints, next to a sample bar:\n* XP, Rested XP, Rested Bonus, Quest XP\n* Reputation by standing, and Renown\n* Honor\nChange any colour and the palette becomes Custom."] = "예시 바 옆에서 경험치 바에 사용되는 모든 색상을 확인할 수 있습니다:\n* 경험치, 휴식 경험치, 휴식 보너스, 퀘스트 경험치\n* 평판 등급별 평판 및 명성\n* 명예 점수\n색상을 하나라도 변경하면 팔레트가 사용자 지정으로 바뀝니다."
L["Every empty slot in the combined backpack looks the same, instead of showing its bag's picture."] = "통합 배낭의 모든 빈 슬롯을 각 가방의 그림 대신 동일한 모양으로 표시합니다."
L["Every key that opens a radial on the character you're playing."] = "현재 플레이 중인 캐릭터에서 방사형 메뉴를 여는 모든 키입니다."
L["Every module of this addon starts switched off.\nTo begin, open the settings and enable the modules you want to use."] = "이 애드온의 모든 모듈은 처음에 비활성화되어 있습니다.\n시작하려면 설정을 열고 사용할 모듈을 활성화하세요."
L["Every other character copies its settings from this one."] = "다른 모든 캐릭터가 이 캐릭터의 설정을 복사합니다."
L["Every other line."] = "한 줄씩 건너뛰기"
L["Every resource bar colour in one window, next to the bars. Palettes:\n* FlareUI (default)\n* Blizzard"] = "모든 자원 바 색상을 바 옆의 하나의 창에서 확인할 수 있습니다. 팔레트:\n* FlareUI (기본값)\n* 블리자드"
L["Every unit frame colour in one window, next to the frames. Palettes:\n* FlareUI: softer, darker tones (default)\n* Blizzard: the game's own"] = "모든 유닛 프레임 색상을 프레임 옆의 하나의 창에서 확인할 수 있습니다. 팔레트:\n* FlareUI: 더 부드럽고 어두운 색조 (기본값)\n* 블리자드: 게임 기본 색상"
L["Everyone"] = "모두"
