L["Everything starts switched off. This short tour shows you what each part does, and you choose the ones you want as you go."] = "모든 기능은 처음에 비활성화되어 있습니다. 이 간단한 안내를 통해 각 기능을 살펴보고 원하는 기능을 선택할 수 있습니다."
L["Everything you need, one key away."] = "필요한 모든 기능을 키 하나로 이용하세요."
