L["Finished objectives stay on the list."] = "완료한 목표를 목록에 계속 표시합니다."
L["Finished quests are turned in when you talk to the NPC. Some always wait for you: repeatable and daily quests, a reward to choose, a gold cost, or battleground marks to hand in."] = "NPC와 대화하면 완료한 퀘스트를 자동으로 제출합니다. 다음 퀘스트는 항상 직접 완료해야 합니다: 반복 및 일일 퀘스트, 보상을 선택해야 하는 퀘스트, 골드 비용이 드는 퀘스트, 전장 징표를 제출해야 하는 퀘스트."
L["Finished quests get a green \"(Complete)\" after their name."] = "완료한 퀘스트는 이름 뒤에 녹색 \"(완료)\"가 표시됩니다."
L["First Name"] = "이름"
L["Last Name"] = "성"
