L["FlareUI Button"] = "FlareUI 버튼"
L["FlareUI caught errors"] = "FlareUI가 감지한 오류"
L["FlareUI copied this character's interface settings from %s.\n\nReload now to finish applying them. Until you do, some of Blizzard's own panels - Edit Mode in particular - can throw errors."] = "FlareUI가 이 캐릭터의 인터페이스 설정을 %s에서 복사했습니다.\n\n설정을 완전히 적용하려면 지금 다시 불러오세요. 다시 불러오기 전까지는 특히 편집 모드와 같은 블리자드 기본 패널에서 오류가 발생할 수 있습니다."
L["FlareUI Debuffs"] = "FlareUI 약화 효과"
L["FlareUI Edit Mode Layout"] = "FlareUI 편집 모드 레이아웃"
L["FlareUI is the default. Change any colour and it becomes Custom. Apply keeps your choice."] = "FlareUI가 기본값입니다. 색상을 하나라도 변경하면 사용자 지정으로 바뀝니다. 적용을 누르면 선택한 설정이 유지됩니다."
L["FlareUI Loot Feed"] = "FlareUI 전리품 알림"
L["FlareUI Loot Rolls"] = "FlareUI 전리품 주사위"
L["FlareUI Minimap Button"] = "FlareUI 미니맵 버튼"
L["FlareUI Settings"] = "FlareUI 설정"
L["FlareUI starts %s after a reload."] = "FlareUI는 다시 불러온 후 %s 상태로 시작합니다."
L["FlareUI Style"] = "FlareUI 스타일"
L["FlareUI Thick"] = "FlareUI 굵게"
L["FlareUI Thin"] = "FlareUI 얇게"
L["FlareUI's border in place of the bronze frame on every bar's buttons: main, pet, stance, possess, totem and vehicle bars. Only the border changes."] = "주 행동 바, 소환수 바, 태세 바, 빙의 바, 토템 바 및 탈것 바의 모든 버튼에서 청동색 프레임 대신 FlareUI 테두리를 사용합니다. 테두리만 변경됩니다."
L["FlareUI's border round each bag slot:\n* Off: Blizzard's own slots, for example when another addon skins your bags\n* Thin Borders: a thin border\n* Thick Borders: a thicker frame\n* Colour by Rarity: the border in the item's quality colour"] = "각 가방 슬롯에 FlareUI 테두리를 적용합니다:\n* 끄기: 다른 애드온으로 가방 외형을 변경하는 경우 등에 사용하는 블리자드 기본 슬롯입니다.\n* 얇은 테두리: 얇은 테두리를 표시합니다.\n* 두꺼운 테두리: 더 두꺼운 프레임을 표시합니다.\n* 희귀도별 색상: 아이템 품질에 해당하는 색상의 테두리를 표시합니다."
L["FlareUI's files didn't load completely. Restart the game. If this keeps happening, reinstall FlareUI."] = "FlareUI 파일이 완전히 로드되지 않았습니다. 게임을 다시 시작하세요. 문제가 계속되면 FlareUI를 다시 설치하세요."
L["FlareUI's look on the Cooldown Manager:\n* Tracked Bars like FlareUI's cast bars\n* Icons with FlareUI's borders"] = "재사용 대기시간 관리자에 FlareUI 스타일을 적용합니다:\n* FlareUI 시전 바와 같은 추적 바\n* FlareUI 테두리가 적용된 아이콘"
L["FlareUI's loot roll window replaces Blizzard's roll frames:\n* Need, Greed and Pass for each item\n* Everyone's choice and roll as they come in\n* Who leads, then who won"] = "FlareUI 전리품 주사위 창이 블리자드 주사위 프레임을 대체합니다:\n* 각 아이템에 대해 차비, 입찰 및 포기 선택\n* 참가자들의 선택과 주사위 결과를 실시간으로 표시\n* 주사위 결과 순위와 최종 획득자 표시"
L["FlareUI's own button, for opening these settings. While Drawer Style isn't Off, it sits in the drawer."] = "이 설정을 열기 위한 FlareUI 전용 버튼입니다. 보관함 스타일이 끄기가 아니면 보관함 안에 배치됩니다."
L["FlareUI's own nameplates, for enemies and friends."] = "FlareUI 전용 적 및 아군 이름표입니다."
L["FlareUI's own frames already sit where the layout expects them"] = "FlareUI 전용 프레임은 이미 레이아웃에서 지정한 위치에 배치되어 있습니다."
L["FlareUI's own quest tracker."] = "FlareUI 전용 퀘스트 추적기입니다."
L["FlareUI's XP bar, with your watched reputation or honor:\n* Off: Blizzard's bars\n* Single: one bar, XP (reputation or honor at max level)\n* Split: XP and reputation side by side\n* Double: two bars, the second below the first"] = "추적 중인 평판 또는 명예 점수를 함께 표시하는 FlareUI 경험치 바입니다:\n* 끄기: 블리자드 기본 바\n* 단일: 하나의 바에 경험치를 표시합니다. (최대 레벨에서는 평판 또는 명예 점수)\n* 분할: 경험치와 평판을 나란히 표시합니다.\n* 이중: 두 개의 바를 사용하며 두 번째 바는 첫 번째 바 아래에 표시됩니다."
L["Flash When Targeted"] = "대상으로 지정되면 점멸"
L["Flashes the taskbar and plays a sound for:\n* Ready checks\n* Summons and resurrections\n* Group invites\n* Dungeon queues"] = "다음 상황에서 작업 표시줄을 점멸시키고 소리를 재생합니다:\n* 준비 확인\n* 소환 및 부활\n* 파티 초대\n* 던전 대기열"
