L["Flip Portrait"] = "초상화 뒤집기"
L["Flips the frame to face the player frame. In FlareUI and Forever Style, only the bars flip."] = "프레임이 플레이어 프레임을 향하도록 뒤집습니다. FlareUI 및 Forever 스타일에서는 바만 뒤집힙니다."
