L["Gamepad mode: the stick press that opens this radial. Click, then press L3 or R3, alone or with LT, RT or both held."] = "게임패드 모드: 스틱 버튼을 눌러 이 방사형 메뉴를 엽니다. 클릭한 다음 L3 또는 R3을 누르세요. LT, RT 또는 두 버튼을 함께 누른 상태에서도 사용할 수 있습니다."
