L["Gold on This Realm"] = "이 서버의 골드"
L["Gone once your interrupt is ready. Turn on Kick Ready Colour to colour the bar then."] = "차단 기술을 사용할 수 있게 되면 사라집니다. 이때 바의 색상을 변경하려면 차단 준비 색상을 활성화하세요."
L["Good dog. All done!"] = "착한 강아지네요. 모두 완료했습니다!"
