L["Got alts? Copies one character's interface options, Edit Mode layout, chat and bag settings to your others."] = "부캐릭터가 있나요? 한 캐릭터의 인터페이스 옵션, 편집 모드 레이아웃, 채팅 및 가방 설정을 다른 캐릭터에 복사합니다."
L["Greed"] = "입찰"
L["Grey items worth money show a coin all the time, not only at a vendor."] = "골드 가치가 있는 회색 아이템에 상인을 이용할 때뿐 아니라 항상 동전 표시를 보여줍니다."
L["Grey Out Known Items"] = "이미 알고 있는 아이템 흐리게 표시"
