L["Instant"] = "즉시"
L["Integrated Bag Buttons"] = "통합 가방 버튼"
L["Intellect"] = "지능"
L["Interactive"] = "상호작용"
L["Interface"] = "인터페이스"
L["Interface Scale"] = "인터페이스 배율"
L["Interrupted"] = "차단됨"
L["Into this profile (the ticked parts are replaced)"] = "이 프로필에 적용합니다. (선택한 항목이 교체됩니다.)"
L["inv pls, I have water"] = "초대 부탁해요, 물 있어요"
L["Invalid coordinates. Try |cffffff00/way|r for usage."] = "잘못된 좌표입니다. 사용법을 확인하려면 |cffffff00/way|r를 입력하세요."
L["It changes the next time you log in."] = "다음에 로그인할 때 변경됩니다."
L["It needs a key. After the reload, FlareUI opens the page where you choose one."] = "단축키가 필요합니다. UI를 다시 불러오면 FlareUI에서 단축키를 선택하는 페이지를 엽니다."
L["It starts at 85%."] = "기본값은 85%입니다."
L["It stays hidden in Edit Mode too, and its box leaves Edit Mode's list of frames."] = "편집 모드에서도 계속 숨겨지며, 해당 프레임은 편집 모드의 프레임 목록에서도 제외됩니다."
L["It wins over any other radial on the same key."] = "같은 키에 지정된 다른 모든 방사형 메뉴보다 우선합니다."
L["It's also at the bottom of the About page in /fui."] = "/fui의 정보 페이지 맨 아래에서도 확인할 수 있습니다."
L["It's on You"] = "자신에게 적용됨"
L["It's saved and switched on right away"] = "저장과 동시에 바로 활성화됩니다."
L["Item"] = "아이템"
L["Item and Spell Icons"] = "아이템 및 주문 아이콘"
L["Item counts and charges."] = "아이템 개수 및 충전 횟수입니다."
L["Item counts and spell charges on the buttons."] = "버튼에 아이템 개수 및 주문 충전 횟수를 표시합니다."
L["Item ID"] = "아이템 ID"
L["Item Level"] = "아이템 레벨"
L["Item Level %d"] = "아이템 레벨 %d"
L["Item Slots"] = "아이템 슬롯"
L["Items"] = "아이템"
L["Items below this quality are left out."] = "이 품질보다 낮은 아이템은 제외됩니다."
L["Items that bind when equipped show BoE in the top left corner, until they're bound."] = "착용 시 귀속되는 아이템은 귀속되기 전까지 왼쪽 위 모서리에 BoE가 표시됩니다."
L["Its border takes the tooltip's border colour."] = "테두리에 툴팁의 테두리 색상을 적용합니다."
L["Its font is the player frame's Aura Timers (Unit Frames > Fonts)."] = "플레이어 프레임의 오라 타이머 글꼴을 사용합니다. (유닛 프레임 > 글꼴)"
L["Junk"] = "잡동사니"
L["Junk Coin"] = "잡동사니 동전"
L["Keep"] = "유지"
L["Keep It On"] = "켜진 상태 유지"
