L["Keep Target on Screen"] = "대상을 화면에 유지"
L["Keep this interface scale?"] = "이 인터페이스 배율을 유지하시겠습니까?"
L["Keeps your conversations through reloads and relogs: what players say, and your whispers."] = "UI를 다시 불러오거나 재로그인해도 플레이어들의 대화와 귓속말을 보존합니다."
L["Key"] = "키"
