L["Right-click a colour to put it back."] = "색상을 오른쪽 클릭하면 원래대로 되돌립니다."
L["Right-click a tab and pick Mute Tab to stop only that tab glowing."] = "탭을 오른쪽 클릭하고 탭 음소거를 선택하면 해당 탭만 빛나지 않게 됩니다."
L["Right-click an icon to hide it, or to pick what it casts: a paladin's blessings for everyone, by class or by player, which aura a paladin casts, who gets Thorns, or what goes on each weapon."] = "아이콘을 오른쪽 클릭하면 숨기거나 해당 아이콘이 시전할 효과를 선택할 수 있습니다. 성기사의 축복을 모든 플레이어, 직업별 또는 플레이어별로 지정하거나, 성기사가 시전할 오라, 가시를 받을 대상 또는 각 무기에 적용할 효과를 선택할 수 있습니다."
L["Right-click its icon to remove it."] = "아이콘을 오른쪽 클릭하면 제거합니다."
L["Right-click the button to hide it. Untick FlareUI in Addons in the Drawer to keep it on the minimap."] = "버튼을 오른쪽 클릭하면 숨깁니다. 미니맵에 계속 표시하려면 서랍의 애드온 목록에서 FlareUI 선택을 해제하세요."
L["Right-click the key to clear it."] = "키를 오른쪽 클릭하면 지정된 키를 해제합니다."
L["Right-click the meter's title, or open its gear menu, for Report to Chat: the top 3, 5 or 10 names to Party, Raid, Instance, Guild or your target, after combat."] = "미터 제목을 오른쪽 클릭하거나 톱니바퀴 메뉴를 열어 채팅에 보고를 선택하면 전투 종료 후 상위 3명, 5명 또는 10명의 이름을 파티, 공격대, 인스턴스, 길드 또는 대상에게 보고합니다."
L["Right-click to clear it. A stick with no radial of its own keeps its job (L3 Auto Run, R3 ping)."] = "오른쪽 클릭하면 지정된 키를 해제합니다. 자체 방사형 메뉴가 없는 스틱은 기존 기능을 유지합니다(L3 자동 달리기, R3 신호 보내기)."
L["Right-click to clear it. On a shared key, the narrower radial wins: this character, then class, then faction."] = "오른쪽 클릭하면 지정된 키를 해제합니다. 키를 공유하는 경우 더 구체적인 방사형 메뉴가 우선합니다. 우선순위는 이 캐릭터, 직업, 진영 순입니다."
L["Right-click to hide this reminder."] = "오른쪽 클릭하면 이 알림을 숨깁니다."
L["Right-click with Shift or Ctrl to reset"] = "Shift 또는 Ctrl을 누른 상태에서 오른쪽 클릭하면 초기화합니다."
L["Right-click: hide this button"] = "오른쪽 클릭: 이 버튼 숨기기"
L["Right-click: toggle Fake CM setup mode"] = "오른쪽 클릭: 가짜 재사용 대기시간 관리자 설정 모드 전환"
L["Robes of the Archmage"] = "대마법사의 로브"
L["Rogues and druids: Action Bar 1 doesn't turn to the stealth page in Stealth or Prowl. Druids keep their Cat Form page."] = "도적과 드루이드: 은신 또는 숨기 상태에서도 행동 바 1이 은신 페이지로 전환되지 않습니다. 드루이드는 표범 변신 페이지를 유지합니다."
