L["Shrinks the bag buttons below Blizzard's smallest Size (75). Off: Blizzard's Size above sets it."] = "가방 버튼을 블리자드의 최소 크기(75)보다 작게 줄입니다. 끄면 위의 블리자드 크기 설정이 적용됩니다."
